{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In monkeys, the large polycyclic glycosylated natural product mithramycin achieved only a 0.12 CSF:plasma ratio after systemic dosing, directly demonstrating poor CNS access for a molecule of comparable size and polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Orientin, a highly polar glycosylated polyphenol, was detected at only low levels in rat brain after intravenous administration and was judged unable to cross the blood-brain barrier because of its high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Daptomycin, a large lipopeptide antibiotic, had undetectable CSF concentrations in a human HPLC study despite high serum levels, showing that large peptide antibiotics do not achieve meaningful CNS exposure after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Colistin, a large cyclic peptide antibiotic, showed brain-to-plasma concentration ratios of only 0.021–0.037 in mice after subcutaneous dosing, indicating minimal CNS distribution for a large polar peptide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Madecassoside, a large glycosylated triterpene, was below the lower limit of quantification in rat brain after oral dosing, consistent with inability to cross the blood-brain barrier due to high polarity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Fail: the query is a very large, highly polar, fully ionized glycopeptide antibiotic. Direct CNS-exposure measurements in multiple structurally and physicochemically analogous large glycosylated/peptidic molecules consistently show poor brain and CSF penetration, and no evidence supports meaningful CNS access after systemic administration.",
  "evidence_gaps": [
    "No direct vancomycin CNS pharmacokinetic record is present in the supplied evidence set.",
    "No transporter-mediated uptake or active-influx evidence is available for the query.",
    "Meningitis-induced BBB disruption could modestly increase CSF penetration, but baseline meaningful CNS access is not supported."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

